import{_ as i,a0 as t,w as o,s as d,ao as c,I as p,x as a,a1 as e,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何在 Linux 上使用 Bash 自动化任务 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上使用 Bash 自动化任务 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上使用 Bash 自动化任务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上使用 Bash 自动化任务 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220726 How I use Bash to automate tasks on Linux","title":"如何在 Linux 上使用 Bash 自动化任务","tag":"202208","desc":""},"relativePath":"202208/20220726 How I use Bash to automate tasks on Linux.md","filePath":"[post].md"}'),r={name:"202208/20220726 How I use Bash to automate tasks on Linux.md"};function h(g,s,f,u,k,b){const n=t("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="如何在-linux-上使用-bash-自动化任务" tabindex="-1">如何在 Linux 上使用 Bash 自动化任务 <a class="header-anchor" href="#如何在-linux-上使用-bash-自动化任务" aria-label="Permalink to “如何在 Linux 上使用 Bash 自动化任务”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/30/181814f4v7ahztuaaxwqwg.jpg" alt=""></p><blockquote><p>Bash 有一些方便的自动化功能，可以让我在 Linux 上处理文件时更轻松。</p></blockquote><p>通过 Bash 命令行进行自动化任务是极好的一种方式。不论你使用运行在服务器上的 Linux 进行管理日志文件或其他文件，还是你在个人电脑上整理文件以使桌面保持整洁，使用 Bash 的自动化功能会使你的工作变得更轻松。</p><h3 id="自动执行文件任务-for" tabindex="-1">自动执行文件任务：for <a class="header-anchor" href="#自动执行文件任务-for" aria-label="Permalink to “自动执行文件任务：for”">​</a></h3><p>如果你对一堆文件要同时处理，并且对每个文件进行相同的操作，请使用 <code>for</code> 命令。该命令会遍历文件列表，并执行一个或多个命令。<code>for</code> 命令如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for 变量 in 列表</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>我在示例中添加了额外的空白和换行，来分开 <code>for</code> 命令中不同的部分。看起来好像无法在命令行中同时运行多个命令，不过你可以使用 <code>;</code> 将所有命令放在同一行中，就像这样:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for 变量 in 列表 ; do 命令 ; done</span></span></code></pre></div><p>让我们看看它的实际效果。我使用 <code>for</code> 命令来重命名一些文件。最近，我有一些截图，想要重命名。这些截图名称为 <code>filemgr.png</code> 或 <code>terminal.png</code>，我想将 <code>screenshot</code> 放在每个名称前。我可以使用 <code>for</code> 命令一次性将 30 个文件重命名。这是两个文件的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>filemgr.png  terminal.png</span></span>
<span class="line"><span>$ for f in *.png ; do mv $f screenshot-$f ; done</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>screenshot-filemgr.png  screenshot-terminal.png</span></span></code></pre></div><p><code>for</code> 命令使得在一系列文件中执行一种或多种操作变得容易。你可以用一些有意义的变量名，比如 <code>image</code> 或 <code>screenshot</code>，或者你用示例中“缩写的”变量 <code>f</code>。当我在使用 <code>for</code> 循环写脚本的时候，会选择有意义的变量名。但是当我在命令行中使用 <code>for</code>，我通常会选择缩写变量名，比如 <code>f</code> 代表文件，<code>d</code> 代表目录等。</p><p>不论你选择怎样的变量名，请确保在引用变量时添加 <code>$</code> 符号。这会将变量扩展为你正在处理的文件的名称。在 Bash 提示符下键入 <code>help for</code> 以了解有关 <code>for</code> 命令的更多信息。</p><h3 id="按条件执行-if" tabindex="-1">按条件执行：if <a class="header-anchor" href="#按条件执行-if" aria-label="Permalink to “按条件执行：if”">​</a></h3><p>当你需要对每个文件执行相同操作时，使用 <code>for</code> 循环遍历一些文件很有帮助。但是，如果你需要对某些文件做一些不同的事情怎么办？为此，你需要使用 <code>if</code> 语句进行条件执行。<code>if</code> 语句如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if 测试</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>你也可以使用 <code>if</code>、<code>else</code> 语句进行判断：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if 测试</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>你可以使用 <code>if</code>、<code>elif</code>、<code> else</code> 语句来实现更复杂的程序。当我一次性需要自动处理很多文件时，我会在脚本中使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if 测试1</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>elif 测试2</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>elif 测试3</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p><code>if</code> 命令可以让你进行各种判断，例如判断一个文件是否是一个文件，或者一个文件是否为空文件（零字节）。在命令行中输入 <code>help test</code>，可以立即查看使用 <code>if</code> 语句能够进行的各种测试。</p><p>例如，假设我想清理一个包含几十个文件的日志目录。日志管理中的一个常见任务是删除所有空日志文件，并压缩其他日志。解决这个问题的最简单方法是删除空文件。没有可以完全匹配的 <code>if</code> 测试，但是我们有 <code>-s</code> 选项来判断是否是一个文件，并且判断该文件不是空的（大小不为零）。这与我们想要的相反，但我们可以使用 <code>!</code> 来否定测试，以判断某些内容不是文件或为空。</p><p>让我们用一个示例来看看这个过程。我创建了两个测试文件：一个是空的，另一个包含一些数据。我们可以使用 <code>if</code> 判断，<em>如果</em>文件为空打印消息 <code>empty</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>datafile  emptyfile</span></span>
<span class="line"><span>$ if [ ! -s datafile ] ; then echo &quot;empty&quot; ; fi</span></span>
<span class="line"><span>$ if [ ! -s emptyfile ] ; then echo &quot;empty&quot; ; fi</span></span>
<span class="line"><span>empty</span></span></code></pre></div><p>我们可以将 <code>if</code> 和 <code>for</code> 命令结合起来，检查日志文件列表中的空文件并删除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l</span></span>
<span class="line"><span>total 20</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  1 01:02 log.1</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  2 01:02 log.2</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  3 01:02 log.3</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 0 Jul  4 01:02 log.4</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  5 01:02 log.5</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 0 Jul  6 01:02 log.6</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  7 01:02 log.7</span></span>
<span class="line"><span>$ for f in log.* ; do if [ ! -s $f ] ; then rm -v $f ; fi ; done</span></span>
<span class="line"><span>removed &#39;log.4&#39;</span></span>
<span class="line"><span>removed &#39;log.6&#39;</span></span>
<span class="line"><span>$ ls -l</span></span>
<span class="line"><span>total 20</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  1 01:02 log.1</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  2 01:02 log.2</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  3 01:02 log.3</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  5 01:02 log.5</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  7 01:02 log.7</span></span></code></pre></div><p>使用 <code>if</code> 命令可以在需要时执行一些操作，使脚本变得智能。我经常会在脚本中使用 <code>if</code>，当我需要判断文件在我的系统上存在或不存在时，或者判断脚本正在检查的条目是文件或目录时。使用 <code>if</code> 使得脚本能够根据需要采取不同的操作。</p><hr>`,28)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/22/7/use-bash-automate-tasks-linux"},{default:l(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/22/7/use-bash-automate-tasks-linux",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/jim-hall"},{default:l(()=>[...s[2]||(s[2]=[a("Jim Hall",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lkxed"},{default:l(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/Donkey-Hao"},{default:l(()=>[...s[4]||(s[4]=[a("Donkey-Hao",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:l(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const y=i(r,[["render",h]]);export{w as __pageData,y as default};
